1	static void binder_transaction(struct binder_proc *proc,
2				       struct binder_thread *thread,
3				       struct binder_transaction_data *tr, int reply,
4				       binder_size_t extra_buffers_size)
5	{
6		int ret;
7		struct binder_transaction *t;
8		struct binder_work *w;
9		struct binder_work *tcomplete;
10		binder_size_t buffer_offset = 0;
11		binder_size_t off_start_offset, off_end_offset;
12		binder_size_t off_min;
13		binder_size_t sg_buf_offset, sg_buf_end_offset;
14		binder_size_t user_offset = 0;
15		struct binder_proc *target_proc = NULL;
16		struct binder_thread *target_thread = NULL;
17		struct binder_node *target_node = NULL;
18		struct binder_transaction *in_reply_to = NULL;
19		struct binder_transaction_log_entry *e;
20		uint32_t return_error = 0;
21		uint32_t return_error_param = 0;
22		uint32_t return_error_line = 0;
23		binder_size_t last_fixup_obj_off = 0;
24		binder_size_t last_fixup_min_off = 0;
25		struct binder_context *context = proc->context;
26		int t_debug_id = atomic_inc_return(&binder_last_id);
27		ktime_t t_start_time = ktime_get();
28		char *secctx = NULL;
29		u32 secctx_sz = 0;
30		struct list_head sgc_head;
31		struct list_head pf_head;
32		const void __user *user_buffer = (const void __user *)
33					(uintptr_t)tr->data.ptr.buffer;
34		INIT_LIST_HEAD(&sgc_head);
35		INIT_LIST_HEAD(&pf_head);
36	
37		e = binder_transaction_log_add(&binder_transaction_log);
38		e->debug_id = t_debug_id;
39		e->call_type = reply ? 2 : !!(tr->flags & TF_ONE_WAY);
40		e->from_proc = proc->pid;
41		e->from_thread = thread->pid;
42		e->target_handle = tr->target.handle;
43		e->data_size = tr->data_size;
44		e->offsets_size = tr->offsets_size;
45		strscpy(e->context_name, proc->context->name, BINDERFS_MAX_NAME);
46	
47		binder_inner_proc_lock(proc);
48		binder_set_extended_error(&thread->ee, t_debug_id, BR_OK, 0);
49		binder_inner_proc_unlock(proc);
50	
51		if (reply) {
52			binder_inner_proc_lock(proc);
53			in_reply_to = thread->transaction_stack;
54			if (in_reply_to == NULL) {
55				binder_inner_proc_unlock(proc);
56				binder_user_error("%d:%d got reply transaction with no transaction stack\n",
57						  proc->pid, thread->pid);
58				return_error = BR_FAILED_REPLY;
59				return_error_param = -EPROTO;
60				return_error_line = __LINE__;
61				goto err_empty_call_stack;
62			}
63			if (in_reply_to->to_thread != thread) {
64				spin_lock(&in_reply_to->lock);
65				binder_user_error("%d:%d got reply transaction with bad transaction stack, transaction %d has target %d:%d\n",
66					proc->pid, thread->pid, in_reply_to->debug_id,
67					in_reply_to->to_proc ?
68					in_reply_to->to_proc->pid : 0,
69					in_reply_to->to_thread ?
70					in_reply_to->to_thread->pid : 0);
71				spin_unlock(&in_reply_to->lock);
72				binder_inner_proc_unlock(proc);
73				return_error = BR_FAILED_REPLY;
74				return_error_param = -EPROTO;
75				return_error_line = __LINE__;
76				in_reply_to = NULL;
77				goto err_bad_call_stack;
78			}
79			thread->transaction_stack = in_reply_to->to_parent;
80			binder_inner_proc_unlock(proc);
81			binder_set_nice(in_reply_to->saved_priority);
82			target_thread = binder_get_txn_from_and_acq_inner(in_reply_to);
83			if (target_thread == NULL) {
84				/* annotation for sparse */
85				__release(&target_thread->proc->inner_lock);
86				binder_txn_error("%d:%d reply target not found\n",
87					thread->pid, proc->pid);
88				return_error = BR_DEAD_REPLY;
89				return_error_line = __LINE__;
90				goto err_dead_binder;
91			}
92			if (target_thread->transaction_stack != in_reply_to) {
93				binder_user_error("%d:%d got reply transaction with bad target transaction stack %d, expected %d\n",
94					proc->pid, thread->pid,
95					target_thread->transaction_stack ?
96					target_thread->transaction_stack->debug_id : 0,
97					in_reply_to->debug_id);
98				binder_inner_proc_unlock(target_thread->proc);
99				return_error = BR_FAILED_REPLY;
100				return_error_param = -EPROTO;
101				return_error_line = __LINE__;
102				in_reply_to = NULL;
103				target_thread = NULL;
104				goto err_dead_binder;
105			}
106			target_proc = target_thread->proc;
107			target_proc->tmp_ref++;
108			binder_inner_proc_unlock(target_thread->proc);
109		} else {
110			if (tr->target.handle) {
111				struct binder_ref *ref;
112	
113				/*
114				 * There must already be a strong ref
115				 * on this node. If so, do a strong
116				 * increment on the node to ensure it
117				 * stays alive until the transaction is
118				 * done.
119				 */
120				binder_proc_lock(proc);
121				ref = binder_get_ref_olocked(proc, tr->target.handle,
122							     true);
123				if (ref) {
124					target_node = binder_get_node_refs_for_txn(
125							ref->node, &target_proc,
126							&return_error);
127				} else {
128					binder_user_error("%d:%d got transaction to invalid handle, %u\n",
129							  proc->pid, thread->pid, tr->target.handle);
130					return_error = BR_FAILED_REPLY;
131				}
132				binder_proc_unlock(proc);
133			} else {
134				mutex_lock(&context->context_mgr_node_lock);
135				target_node = context->binder_context_mgr_node;
136				if (target_node)
137					target_node = binder_get_node_refs_for_txn(
138							target_node, &target_proc,
139							&return_error);
140				else
141					return_error = BR_DEAD_REPLY;
142				mutex_unlock(&context->context_mgr_node_lock);
143				if (target_node && target_proc->pid == proc->pid) {
144					binder_user_error("%d:%d got transaction to context manager from process owning it\n",
145							  proc->pid, thread->pid);
146					return_error = BR_FAILED_REPLY;
147					return_error_param = -EINVAL;
148					return_error_line = __LINE__;
149					goto err_invalid_target_handle;
150				}
151			}
152			if (!target_node) {
153				binder_txn_error("%d:%d cannot find target node\n",
154					thread->pid, proc->pid);
155				/*
156				 * return_error is set above
157				 */
158				return_error_param = -EINVAL;
159				return_error_line = __LINE__;
160				goto err_dead_binder;
161			}
162			e->to_node = target_node->debug_id;
163			if (WARN_ON(proc == target_proc)) {
164				binder_txn_error("%d:%d self transactions not allowed\n",
165					thread->pid, proc->pid);
166				return_error = BR_FAILED_REPLY;
167				return_error_param = -EINVAL;
168				return_error_line = __LINE__;
169				goto err_invalid_target_handle;
170			}
171			if (security_binder_transaction(proc->cred,
172							target_proc->cred) < 0) {
173				binder_txn_error("%d:%d transaction credentials failed\n",
174					thread->pid, proc->pid);
175				return_error = BR_FAILED_REPLY;
176				return_error_param = -EPERM;
177				return_error_line = __LINE__;
178				goto err_invalid_target_handle;
179			}
180			binder_inner_proc_lock(proc);
181	
182			w = list_first_entry_or_null(&thread->todo,
183						     struct binder_work, entry);
184			if (!(tr->flags & TF_ONE_WAY) && w &&
185			    w->type == BINDER_WORK_TRANSACTION) {
186				/*
187				 * Do not allow new outgoing transaction from a
188				 * thread that has a transaction at the head of
189				 * its todo list. Only need to check the head
190				 * because binder_select_thread_ilocked picks a
191				 * thread from proc->waiting_threads to enqueue
192				 * the transaction, and nothing is queued to the
193				 * todo list while the thread is on waiting_threads.
194				 */
195				binder_user_error("%d:%d new transaction not allowed when there is a transaction on thread todo\n",
196						  proc->pid, thread->pid);
197				binder_inner_proc_unlock(proc);
198				return_error = BR_FAILED_REPLY;
199				return_error_param = -EPROTO;
200				return_error_line = __LINE__;
201				goto err_bad_todo_list;
202			}
203	
204			if (!(tr->flags & TF_ONE_WAY) && thread->transaction_stack) {
205				struct binder_transaction *tmp;
206	
207				tmp = thread->transaction_stack;
208				if (tmp->to_thread != thread) {
209					spin_lock(&tmp->lock);
210					binder_user_error("%d:%d got new transaction with bad transaction stack, transaction %d has target %d:%d\n",
211						proc->pid, thread->pid, tmp->debug_id,
212						tmp->to_proc ? tmp->to_proc->pid : 0,
213						tmp->to_thread ?
214						tmp->to_thread->pid : 0);
215					spin_unlock(&tmp->lock);
216					binder_inner_proc_unlock(proc);
217					return_error = BR_FAILED_REPLY;
218					return_error_param = -EPROTO;
219					return_error_line = __LINE__;
220					goto err_bad_call_stack;
221				}
222				while (tmp) {
223					struct binder_thread *from;
224	
225					spin_lock(&tmp->lock);
226					from = tmp->from;
227					if (from && from->proc == target_proc) {
228						atomic_inc(&from->tmp_ref);
229						target_thread = from;
230						spin_unlock(&tmp->lock);
231						break;
232					}
233					spin_unlock(&tmp->lock);
234					tmp = tmp->from_parent;
235				}
236			}
237			binder_inner_proc_unlock(proc);
238		}
239		if (target_thread)
240			e->to_thread = target_thread->pid;
241		e->to_proc = target_proc->pid;
242	
243		/* TODO: reuse incoming transaction for reply */
244		t = kzalloc(sizeof(*t), GFP_KERNEL);
245		if (t == NULL) {
246			binder_txn_error("%d:%d cannot allocate transaction\n",
247				thread->pid, proc->pid);
248			return_error = BR_FAILED_REPLY;
249			return_error_param = -ENOMEM;
250			return_error_line = __LINE__;
251			goto err_alloc_t_failed;
252		}
253		INIT_LIST_HEAD(&t->fd_fixups);
254		binder_stats_created(BINDER_STAT_TRANSACTION);
255		spin_lock_init(&t->lock);
256	
257		tcomplete = kzalloc(sizeof(*tcomplete), GFP_KERNEL);
258		if (tcomplete == NULL) {
259			binder_txn_error("%d:%d cannot allocate work for transaction\n",
260				thread->pid, proc->pid);
261			return_error = BR_FAILED_REPLY;
262			return_error_param = -ENOMEM;
263			return_error_line = __LINE__;
264			goto err_alloc_tcomplete_failed;
265		}
266		binder_stats_created(BINDER_STAT_TRANSACTION_COMPLETE);
267	
268		t->debug_id = t_debug_id;
269		t->start_time = t_start_time;
270	
271		if (reply)
272			binder_debug(BINDER_DEBUG_TRANSACTION,
273				     "%d:%d BC_REPLY %d -> %d:%d, data %016llx-%016llx size %lld-%lld-%lld\n",
274				     proc->pid, thread->pid, t->debug_id,
275				     target_proc->pid, target_thread->pid,
276				     (u64)tr->data.ptr.buffer,
277				     (u64)tr->data.ptr.offsets,
278				     (u64)tr->data_size, (u64)tr->offsets_size,
279				     (u64)extra_buffers_size);
280		else
281			binder_debug(BINDER_DEBUG_TRANSACTION,
282				     "%d:%d BC_TRANSACTION %d -> %d - node %d, data %016llx-%016llx size %lld-%lld-%lld\n",
283				     proc->pid, thread->pid, t->debug_id,
284				     target_proc->pid, target_node->debug_id,
285				     (u64)tr->data.ptr.buffer,
286				     (u64)tr->data.ptr.offsets,
287				     (u64)tr->data_size, (u64)tr->offsets_size,
288				     (u64)extra_buffers_size);
289	
290		if (!reply && !(tr->flags & TF_ONE_WAY))
291			t->from = thread;
292		else
293			t->from = NULL;
294		t->from_pid = proc->pid;
295		t->from_tid = thread->pid;
296		t->sender_euid = task_euid(proc->tsk);
297		t->to_proc = target_proc;
298		t->to_thread = target_thread;
299		t->code = tr->code;
300		t->flags = tr->flags;
301		t->priority = task_nice(current);
302	
303		if (target_node && target_node->txn_security_ctx) {
304			u32 secid;
305			size_t added_size;
306	
307			security_cred_getsecid(proc->cred, &secid);
308			ret = security_secid_to_secctx(secid, &secctx, &secctx_sz);
309			if (ret) {
310				binder_txn_error("%d:%d failed to get security context\n",
311					thread->pid, proc->pid);
312				return_error = BR_FAILED_REPLY;
313				return_error_param = ret;
314				return_error_line = __LINE__;
315				goto err_get_secctx_failed;
316			}
317			added_size = ALIGN(secctx_sz, sizeof(u64));
318			extra_buffers_size += added_size;
319			if (extra_buffers_size < added_size) {
320				binder_txn_error("%d:%d integer overflow of extra_buffers_size\n",
321					thread->pid, proc->pid);
322				return_error = BR_FAILED_REPLY;
323				return_error_param = -EINVAL;
324				return_error_line = __LINE__;
325				goto err_bad_extra_size;
326			}
327		}
328	
329		trace_binder_transaction(reply, t, target_node);
330	
331		t->buffer = binder_alloc_new_buf(&target_proc->alloc, tr->data_size,
332			tr->offsets_size, extra_buffers_size,
333			!reply && (t->flags & TF_ONE_WAY));
334		if (IS_ERR(t->buffer)) {
335			char *s;
336	
337			ret = PTR_ERR(t->buffer);
338			s = (ret == -ESRCH) ? ": vma cleared, target dead or dying"
339				: (ret == -ENOSPC) ? ": no space left"
340				: (ret == -ENOMEM) ? ": memory allocation failed"
341				: "";
342			binder_txn_error("cannot allocate buffer%s", s);
343	
344			return_error_param = PTR_ERR(t->buffer);
345			return_error = return_error_param == -ESRCH ?
346				BR_DEAD_REPLY : BR_FAILED_REPLY;
347			return_error_line = __LINE__;
348			t->buffer = NULL;
349			goto err_binder_alloc_buf_failed;
350		}
351		if (secctx) {
352			int err;
353			size_t buf_offset = ALIGN(tr->data_size, sizeof(void *)) +
354					    ALIGN(tr->offsets_size, sizeof(void *)) +
355					    ALIGN(extra_buffers_size, sizeof(void *)) -
356					    ALIGN(secctx_sz, sizeof(u64));
357	
358			t->security_ctx = t->buffer->user_data + buf_offset;
359			err = binder_alloc_copy_to_buffer(&target_proc->alloc,
360							  t->buffer, buf_offset,
361							  secctx, secctx_sz);
362			if (err) {
363				t->security_ctx = 0;
364				WARN_ON(1);
365			}
366			security_release_secctx(secctx, secctx_sz);
367			secctx = NULL;
368		}
369		t->buffer->debug_id = t->debug_id;
370		t->buffer->transaction = t;
371		t->buffer->target_node = target_node;
372		t->buffer->clear_on_free = !!(t->flags & TF_CLEAR_BUF);
373		trace_binder_transaction_alloc_buf(t->buffer);
374	
375		if (binder_alloc_copy_user_to_buffer(
376					&target_proc->alloc,
377					t->buffer,
378					ALIGN(tr->data_size, sizeof(void *)),
379					(const void __user *)
380						(uintptr_t)tr->data.ptr.offsets,
381					tr->offsets_size)) {
382			binder_user_error("%d:%d got transaction with invalid offsets ptr\n",
383					proc->pid, thread->pid);
384			return_error = BR_FAILED_REPLY;
385			return_error_param = -EFAULT;
386			return_error_line = __LINE__;
387			goto err_copy_data_failed;
388		}
389		if (!IS_ALIGNED(tr->offsets_size, sizeof(binder_size_t))) {
390			binder_user_error("%d:%d got transaction with invalid offsets size, %lld\n",
391					proc->pid, thread->pid, (u64)tr->offsets_size);
392			return_error = BR_FAILED_REPLY;
393			return_error_param = -EINVAL;
394			return_error_line = __LINE__;
395			goto err_bad_offset;
396		}
397		if (!IS_ALIGNED(extra_buffers_size, sizeof(u64))) {
398			binder_user_error("%d:%d got transaction with unaligned buffers size, %lld\n",
399					  proc->pid, thread->pid,
400					  (u64)extra_buffers_size);
401			return_error = BR_FAILED_REPLY;
402			return_error_param = -EINVAL;
403			return_error_line = __LINE__;
404			goto err_bad_offset;
405		}
406		off_start_offset = ALIGN(tr->data_size, sizeof(void *));
407		buffer_offset = off_start_offset;
408		off_end_offset = off_start_offset + tr->offsets_size;
409		sg_buf_offset = ALIGN(off_end_offset, sizeof(void *));
410		sg_buf_end_offset = sg_buf_offset + extra_buffers_size -
411			ALIGN(secctx_sz, sizeof(u64));
412		off_min = 0;
413		for (buffer_offset = off_start_offset; buffer_offset < off_end_offset;
414		     buffer_offset += sizeof(binder_size_t)) {
415			struct binder_object_header *hdr;
416			size_t object_size;
417			struct binder_object object;
418			binder_size_t object_offset;
419			binder_size_t copy_size;
420	
421			if (binder_alloc_copy_from_buffer(&target_proc->alloc,
422							  &object_offset,
423							  t->buffer,
424							  buffer_offset,
425							  sizeof(object_offset))) {
426				binder_txn_error("%d:%d copy offset from buffer failed\n",
427					thread->pid, proc->pid);
428				return_error = BR_FAILED_REPLY;
429				return_error_param = -EINVAL;
430				return_error_line = __LINE__;
431				goto err_bad_offset;
432			}
433	
434			/*
435			 * Copy the source user buffer up to the next object
436			 * that will be processed.
437			 */
438			copy_size = object_offset - user_offset;
439			if (copy_size && (user_offset > object_offset ||
440					binder_alloc_copy_user_to_buffer(
441						&target_proc->alloc,
442						t->buffer, user_offset,
443						user_buffer + user_offset,
444						copy_size))) {
445				binder_user_error("%d:%d got transaction with invalid data ptr\n",
446						proc->pid, thread->pid);
447				return_error = BR_FAILED_REPLY;
448				return_error_param = -EFAULT;
449				return_error_line = __LINE__;
450				goto err_copy_data_failed;
451			}
452			object_size = binder_get_object(target_proc, user_buffer,
453					t->buffer, object_offset, &object);
454			if (object_size == 0 || object_offset < off_min) {
455				binder_user_error("%d:%d got transaction with invalid offset (%lld, min %lld max %lld) or object.\n",
456						  proc->pid, thread->pid,
457						  (u64)object_offset,
458						  (u64)off_min,
459						  (u64)t->buffer->data_size);
460				return_error = BR_FAILED_REPLY;
461				return_error_param = -EINVAL;
462				return_error_line = __LINE__;
463				goto err_bad_offset;
464			}
465			/*
466			 * Set offset to the next buffer fragment to be
467			 * copied
468			 */
469			user_offset = object_offset + object_size;
470	
471			hdr = &object.hdr;
472			off_min = object_offset + object_size;
473			switch (hdr->type) {
474			case BINDER_TYPE_BINDER:
475			case BINDER_TYPE_WEAK_BINDER: {
476				struct flat_binder_object *fp;
477	
478				fp = to_flat_binder_object(hdr);
479				ret = binder_translate_binder(fp, t, thread);
480	
481				if (ret < 0 ||
482				    binder_alloc_copy_to_buffer(&target_proc->alloc,
483								t->buffer,
484								object_offset,
485								fp, sizeof(*fp))) {
486					binder_txn_error("%d:%d translate binder failed\n",
487						thread->pid, proc->pid);
488					return_error = BR_FAILED_REPLY;
489					return_error_param = ret;
490					return_error_line = __LINE__;
491					goto err_translate_failed;
492				}
493			} break;
494			case BINDER_TYPE_HANDLE:
495			case BINDER_TYPE_WEAK_HANDLE: {
496				struct flat_binder_object *fp;
497	
498				fp = to_flat_binder_object(hdr);
499				ret = binder_translate_handle(fp, t, thread);
500				if (ret < 0 ||
501				    binder_alloc_copy_to_buffer(&target_proc->alloc,
502								t->buffer,
503								object_offset,
504								fp, sizeof(*fp))) {
505					binder_txn_error("%d:%d translate handle failed\n",
506						thread->pid, proc->pid);
507					return_error = BR_FAILED_REPLY;
508					return_error_param = ret;
509					return_error_line = __LINE__;
510					goto err_translate_failed;
511				}
512			} break;
513	
514			case BINDER_TYPE_FD: {
515				struct binder_fd_object *fp = to_binder_fd_object(hdr);
516				binder_size_t fd_offset = object_offset +
517					(uintptr_t)&fp->fd - (uintptr_t)fp;
518				int ret = binder_translate_fd(fp->fd, fd_offset, t,
519							      thread, in_reply_to);
520	
521				fp->pad_binder = 0;
522				if (ret < 0 ||
523				    binder_alloc_copy_to_buffer(&target_proc->alloc,
524								t->buffer,
525								object_offset,
526								fp, sizeof(*fp))) {
527					binder_txn_error("%d:%d translate fd failed\n",
528						thread->pid, proc->pid);
529					return_error = BR_FAILED_REPLY;
530					return_error_param = ret;
531					return_error_line = __LINE__;
532					goto err_translate_failed;
533				}
534			} break;
535			case BINDER_TYPE_FDA: {
536				struct binder_object ptr_object;
537				binder_size_t parent_offset;
538				struct binder_object user_object;
539				size_t user_parent_size;
540				struct binder_fd_array_object *fda =
541					to_binder_fd_array_object(hdr);
542				size_t num_valid = (buffer_offset - off_start_offset) /
543							sizeof(binder_size_t);
544				struct binder_buffer_object *parent =
545					binder_validate_ptr(target_proc, t->buffer,
546							    &ptr_object, fda->parent,
547							    off_start_offset,
548							    &parent_offset,
549							    num_valid);
550				if (!parent) {
551					binder_user_error("%d:%d got transaction with invalid parent offset or type\n",
552							  proc->pid, thread->pid);
553					return_error = BR_FAILED_REPLY;
554					return_error_param = -EINVAL;
555					return_error_line = __LINE__;
556					goto err_bad_parent;
557				}
558				if (!binder_validate_fixup(target_proc, t->buffer,
559							   off_start_offset,
560							   parent_offset,
561							   fda->parent_offset,
562							   last_fixup_obj_off,
563							   last_fixup_min_off)) {
564					binder_user_error("%d:%d got transaction with out-of-order buffer fixup\n",
565							  proc->pid, thread->pid);
566					return_error = BR_FAILED_REPLY;
567					return_error_param = -EINVAL;
568					return_error_line = __LINE__;
569					goto err_bad_parent;
570				}
571				/*
572				 * We need to read the user version of the parent
573				 * object to get the original user offset
574				 */
575				user_parent_size =
576					binder_get_object(proc, user_buffer, t->buffer,
577							  parent_offset, &user_object);
578				if (user_parent_size != sizeof(user_object.bbo)) {
579					binder_user_error("%d:%d invalid ptr object size: %zd vs %zd\n",
580							  proc->pid, thread->pid,
581							  user_parent_size,
582							  sizeof(user_object.bbo));
583					return_error = BR_FAILED_REPLY;
584					return_error_param = -EINVAL;
585					return_error_line = __LINE__;
586					goto err_bad_parent;
587				}
588				ret = binder_translate_fd_array(&pf_head, fda,
589								user_buffer, parent,
590								&user_object.bbo, t,
591								thread, in_reply_to);
592				if (!ret)
593					ret = binder_alloc_copy_to_buffer(&target_proc->alloc,
594									  t->buffer,
595									  object_offset,
596									  fda, sizeof(*fda));
597				if (ret) {
598					binder_txn_error("%d:%d translate fd array failed\n",
599						thread->pid, proc->pid);
600					return_error = BR_FAILED_REPLY;
601					return_error_param = ret > 0 ? -EINVAL : ret;
602					return_error_line = __LINE__;
603					goto err_translate_failed;
604				}
605				last_fixup_obj_off = parent_offset;
606				last_fixup_min_off =
607					fda->parent_offset + sizeof(u32) * fda->num_fds;
608			} break;
609			case BINDER_TYPE_PTR: {
610				struct binder_buffer_object *bp =
611					to_binder_buffer_object(hdr);
612				size_t buf_left = sg_buf_end_offset - sg_buf_offset;
613				size_t num_valid;
614	
615				if (bp->length > buf_left) {
616					binder_user_error("%d:%d got transaction with too large buffer\n",
617							  proc->pid, thread->pid);
618					return_error = BR_FAILED_REPLY;
619					return_error_param = -EINVAL;
620					return_error_line = __LINE__;
621					goto err_bad_offset;
622				}
623				ret = binder_defer_copy(&sgc_head, sg_buf_offset,
624					(const void __user *)(uintptr_t)bp->buffer,
625					bp->length);
626				if (ret) {
627					binder_txn_error("%d:%d deferred copy failed\n",
628						thread->pid, proc->pid);
629					return_error = BR_FAILED_REPLY;
630					return_error_param = ret;
631					return_error_line = __LINE__;
632					goto err_translate_failed;
633				}
634				/* Fixup buffer pointer to target proc address space */
635				bp->buffer = t->buffer->user_data + sg_buf_offset;
636				sg_buf_offset += ALIGN(bp->length, sizeof(u64));
637	
638				num_valid = (buffer_offset - off_start_offset) /
639						sizeof(binder_size_t);
640				ret = binder_fixup_parent(&pf_head, t,
641							  thread, bp,
642							  off_start_offset,
643							  num_valid,
644							  last_fixup_obj_off,
645							  last_fixup_min_off);
646				if (ret < 0 ||
647				    binder_alloc_copy_to_buffer(&target_proc->alloc,
648								t->buffer,
649								object_offset,
650								bp, sizeof(*bp))) {
651					binder_txn_error("%d:%d failed to fixup parent\n",
652						thread->pid, proc->pid);
653					return_error = BR_FAILED_REPLY;
654					return_error_param = ret;
655					return_error_line = __LINE__;
656					goto err_translate_failed;
657				}
658				last_fixup_obj_off = object_offset;
659				last_fixup_min_off = 0;
660			} break;
661			default:
662				binder_user_error("%d:%d got transaction with invalid object type, %x\n",
663					proc->pid, thread->pid, hdr->type);
664				return_error = BR_FAILED_REPLY;
665				return_error_param = -EINVAL;
666				return_error_line = __LINE__;
667				goto err_bad_object_type;
668			}
669		}
670		/* Done processing objects, copy the rest of the buffer */
671		if (binder_alloc_copy_user_to_buffer(
672					&target_proc->alloc,
673					t->buffer, user_offset,
674					user_buffer + user_offset,
675					tr->data_size - user_offset)) {
676			binder_user_error("%d:%d got transaction with invalid data ptr\n",
677					proc->pid, thread->pid);
678			return_error = BR_FAILED_REPLY;
679			return_error_param = -EFAULT;
680			return_error_line = __LINE__;
681			goto err_copy_data_failed;
682		}
683	
684		ret = binder_do_deferred_txn_copies(&target_proc->alloc, t->buffer,
685						    &sgc_head, &pf_head);
686		if (ret) {
687			binder_user_error("%d:%d got transaction with invalid offsets ptr\n",
688					  proc->pid, thread->pid);
689			return_error = BR_FAILED_REPLY;
690			return_error_param = ret;
691			return_error_line = __LINE__;
692			goto err_copy_data_failed;
693		}
694		if (t->buffer->oneway_spam_suspect)
695			tcomplete->type = BINDER_WORK_TRANSACTION_ONEWAY_SPAM_SUSPECT;
696		else
697			tcomplete->type = BINDER_WORK_TRANSACTION_COMPLETE;
698		t->work.type = BINDER_WORK_TRANSACTION;
699	
700		if (reply) {
701			binder_enqueue_thread_work(thread, tcomplete);
702			binder_inner_proc_lock(target_proc);
703			if (target_thread->is_dead) {
704				return_error = BR_DEAD_REPLY;
705				binder_inner_proc_unlock(target_proc);
706				goto err_dead_proc_or_thread;
707			}
708			BUG_ON(t->buffer->async_transaction != 0);
709			binder_pop_transaction_ilocked(target_thread, in_reply_to);
710			binder_enqueue_thread_work_ilocked(target_thread, &t->work);
711			target_proc->outstanding_txns++;
712			binder_inner_proc_unlock(target_proc);
713			wake_up_interruptible_sync(&target_thread->wait);
714			binder_free_transaction(in_reply_to);
715		} else if (!(t->flags & TF_ONE_WAY)) {
716			BUG_ON(t->buffer->async_transaction != 0);
717			binder_inner_proc_lock(proc);
718			/*
719			 * Defer the TRANSACTION_COMPLETE, so we don't return to
720			 * userspace immediately; this allows the target process to
721			 * immediately start processing this transaction, reducing
722			 * latency. We will then return the TRANSACTION_COMPLETE when
723			 * the target replies (or there is an error).
724			 */
725			binder_enqueue_deferred_thread_work_ilocked(thread, tcomplete);
726			t->need_reply = 1;
727			t->from_parent = thread->transaction_stack;
728			thread->transaction_stack = t;
729			binder_inner_proc_unlock(proc);
730			return_error = binder_proc_transaction(t,
731					target_proc, target_thread);
732			if (return_error) {
733				binder_inner_proc_lock(proc);
734				binder_pop_transaction_ilocked(thread, t);
735				binder_inner_proc_unlock(proc);
736				goto err_dead_proc_or_thread;
737			}
738		} else {
739			BUG_ON(target_node == NULL);
740			BUG_ON(t->buffer->async_transaction != 1);
741			return_error = binder_proc_transaction(t, target_proc, NULL);
742			/*
743			 * Let the caller know when async transaction reaches a frozen
744			 * process and is put in a pending queue, waiting for the target
745			 * process to be unfrozen.
746			 */
747			if (return_error == BR_TRANSACTION_PENDING_FROZEN)
748				tcomplete->type = BINDER_WORK_TRANSACTION_PENDING;
749			binder_enqueue_thread_work(thread, tcomplete);
750			if (return_error &&
751			    return_error != BR_TRANSACTION_PENDING_FROZEN)
752				goto err_dead_proc_or_thread;
753		}
754		if (target_thread)
755			binder_thread_dec_tmpref(target_thread);
756		binder_proc_dec_tmpref(target_proc);
757		if (target_node)
758			binder_dec_node_tmpref(target_node);
759		/*
760		 * write barrier to synchronize with initialization
761		 * of log entry
762		 */
763		smp_wmb();
764		WRITE_ONCE(e->debug_id_done, t_debug_id);
765		return;
766	
767	err_dead_proc_or_thread:
768		binder_txn_error("%d:%d dead process or thread\n",
769			thread->pid, proc->pid);
770		return_error_line = __LINE__;
771		binder_dequeue_work(proc, tcomplete);
772	err_translate_failed:
773	err_bad_object_type:
774	err_bad_offset:
775	err_bad_parent:
776	err_copy_data_failed:
777		binder_cleanup_deferred_txn_lists(&sgc_head, &pf_head);
778		binder_free_txn_fixups(t);
779		trace_binder_transaction_failed_buffer_release(t->buffer);
780		binder_transaction_buffer_release(target_proc, NULL, t->buffer,
781						  buffer_offset, true);
782		if (target_node)
783			binder_dec_node_tmpref(target_node);
784		target_node = NULL;
785		t->buffer->transaction = NULL;
786		binder_alloc_free_buf(&target_proc->alloc, t->buffer);
787	err_binder_alloc_buf_failed:
788	err_bad_extra_size:
789		if (secctx)
790			security_release_secctx(secctx, secctx_sz);
791	err_get_secctx_failed:
792		kfree(tcomplete);
793		binder_stats_deleted(BINDER_STAT_TRANSACTION_COMPLETE);
794	err_alloc_tcomplete_failed:
795		if (trace_binder_txn_latency_free_enabled())
796			binder_txn_latency_free(t);
797		kfree(t);
798		binder_stats_deleted(BINDER_STAT_TRANSACTION);
799	err_alloc_t_failed:
800	err_bad_todo_list:
801	err_bad_call_stack:
802	err_empty_call_stack:
803	err_dead_binder:
804	err_invalid_target_handle:
805		if (target_node) {
806			binder_dec_node(target_node, 1, 0);
807			binder_dec_node_tmpref(target_node);
808		}
809	
810		binder_debug(BINDER_DEBUG_FAILED_TRANSACTION,
811			     "%d:%d transaction %s to %d:%d failed %d/%d/%d, size %lld-%lld line %d\n",
812			     proc->pid, thread->pid, reply ? "reply" :
813			     (tr->flags & TF_ONE_WAY ? "async" : "call"),
814			     target_proc ? target_proc->pid : 0,
815			     target_thread ? target_thread->pid : 0,
816			     t_debug_id, return_error, return_error_param,
817			     (u64)tr->data_size, (u64)tr->offsets_size,
818			     return_error_line);
819	
820		if (target_thread)
821			binder_thread_dec_tmpref(target_thread);
822		if (target_proc)
823			binder_proc_dec_tmpref(target_proc);
824	
825		{
826			struct binder_transaction_log_entry *fe;
827	
828			e->return_error = return_error;
829			e->return_error_param = return_error_param;
830			e->return_error_line = return_error_line;
831			fe = binder_transaction_log_add(&binder_transaction_log_failed);
832			*fe = *e;
833			/*
834			 * write barrier to synchronize with initialization
835			 * of log entry
836			 */
837			smp_wmb();
838			WRITE_ONCE(e->debug_id_done, t_debug_id);
839			WRITE_ONCE(fe->debug_id_done, t_debug_id);
840		}
841	
842		BUG_ON(thread->return_error.cmd != BR_OK);
843		if (in_reply_to) {
844			binder_set_txn_from_error(in_reply_to, t_debug_id,
845					return_error, return_error_param);
846			thread->return_error.cmd = BR_TRANSACTION_COMPLETE;
847			binder_enqueue_thread_work(thread, &thread->return_error.work);
848			binder_send_failed_reply(in_reply_to, return_error);
849		} else {
850			binder_inner_proc_lock(proc);
851			binder_set_extended_error(&thread->ee, t_debug_id,
852					return_error, return_error_param);
853			binder_inner_proc_unlock(proc);
854			thread->return_error.cmd = return_error;
855			binder_enqueue_thread_work(thread, &thread->return_error.work);
856		}
857	}
858

